import randomimport stringfrom odoo import api, fields, models, _, toolsfrom odoo.exceptions import UserErrorclass SaleAgent(models.Model):    _name = "sale.agent"    _rec_name = "full_name"    _description = "Sale Agent Details"    email = fields.Char(string="Email")    password = fields.Char(string="Password")    full_name = fields.Char(string="Full Name")    nic = fields.Char(string="NIC")    mobile = fields.Char(string="Mobile NO")    agent_id = fields.Char(string="Agent ID")    secret_key = fields.Char(string="Secret Key")    crm_team_id = fields.Many2one(comodel_name="crm.team", string="Sales Team")    company_id = fields.Many2one(comodel_name='res.company', string='Company')    user_id = fields.Many2one(comodel_name='res.users', string='User', required=True)    def generate_sequence(self):        length = 6        characters = string.ascii_letters + string.digits        sequence = ''.join(random.choice(characters) for i in range(length))        return sequence    @api.model    def create(self, vals):        if not vals.get('secret_key'):            vals['secret_key'] = self.generate_sequence()        sale_agent = super(SaleAgent, self).create(vals)        sale_agent._update_crm_team_members()        return sale_agent    def write(self, vals):        res = super(SaleAgent, self).write(vals)        self._update_crm_team_members()        return res    def name_get(self):        res = []        for sale_agent in self:            res.append((sale_agent.id, '%s (%s)' % (sale_agent.full_name, sale_agent.emp_id)))        return res    def action_send_agent_invitation(self):        for agent in self:            if not agent.user_id or not agent.user_id.login:                raise UserError(_("The selected agent must have a linked user with a valid email."))            template = self.env.ref('vkd_property_management.sale_agent_invitation_email_template')            template.send_mail(agent.id, force_send=True)    def _update_crm_team_members(self):        for agent in self:            if agent.crm_team_id and agent.user_id:                if agent.user_id.id not in agent.crm_team_id.member_ids.ids:                    agent.crm_team_id.write({                        'member_ids': [(4, agent.user_id.id)]                    })